<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php'; require_admin();
$student=(int)($_GET['student_id']??0);$year=trim($_GET['academic_year']??'');
$sql="SELECT h.*,s.StudentName,s.RollId,c.ClassName,c.Section,sub.SubjectName FROM result_history h JOIN tblstudents s ON s.StudentId=h.student_id JOIN tblclasses c ON c.id=h.class_id JOIN tblsubjects sub ON sub.id=h.subject_id WHERE 1";$p=[];
if($student){$sql.=' AND h.student_id=:sid';$p[':sid']=$student;}if($year){$sql.=' AND h.academic_year=:y';$p[':y']=$year;}$sql.=' ORDER BY h.snapshot_at DESC,h.id DESC LIMIT 500';$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result History | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><div class="srms-toolbar"><a href="dashboard.php" class="btn btn-default">← Dashboard</a><a href="academic-periods.php" class="btn btn-primary">Academic Periods</a></div><h2>Result Version History</h2><p class="text-muted">This is a read-only audit trail of marks before they were changed.</p><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Date</th><th>Student</th><th>Subject</th><th>Period</th><th>Previous Marks</th><th>Status</th><th>Action</th><th>Changed By</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['snapshot_at']);?></td><td><?php echo e($r['StudentName'].' ('.$r['RollId'].')');?><br><small><?php echo e($r['ClassName'].' '.$r['Section']);?></small></td><td><?php echo e($r['SubjectName']);?></td><td><?php echo e($r['academic_year'].' / '.$r['term'].' / '.$r['exam_type']);?></td><td><strong><?php echo (int)$r['marks'];?> / <?php echo (int)$r['max_marks'];?></strong></td><td><?php echo e(result_status_label($r['result_status']));?></td><td><?php echo e($r['action']);?></td><td><?php echo e($r['changed_by_type'].' #'.($r['changed_by']??'—'));?></td><td><?php echo e($r['reason']??'');?></td></tr><?php endforeach;?></tbody></table></div></div></main></div></div></div></div></body></html>
